(() => {
let frame=0,last=0,elapsed=0,running=false,lines=[],duration=0,index=-1,element=null,fade=0;
function step(now){if(!running)return;if(last)elapsed+=Math.min(now-last,100);last=now;const ratio=Math.min(1,elapsed/duration);let sum=0,selected=lines.length-1;for(let n=0;n<lines.length;n++){sum+=lines[n].weight;if(ratio<sum){selected=n;break}}if(selected!==index&&element){index=selected;const target=lines[index].text;if(!element.textContent)element.textContent=target;else{element.classList.add('changing');clearTimeout(fade);fade=setTimeout(()=>{if(element){element.textContent=target;element.classList.remove('changing')}},140)}}frame=requestAnimationFrame(step)}
window.CinemaCaptions={mount(text,seconds){this.reset();element=document.querySelector('.movie-subtitle');const sentences=text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[text];const segments=[];for(const sentence of sentences){let s=sentence.trim();if(s.length>145){const parts=s.split(/,\s+|;\s+/);for(const p of parts)segments.push(p.trim())}else segments.push(s)}const total=segments.reduce((n,s)=>n+s.length,0);lines=segments.filter(Boolean).map(s=>({text:s,weight:s.length/total}));duration=seconds*1000;if(element)element.textContent=lines[0]?.text||text;index=0},play(active){if(active&&!running){running=true;last=0;frame=requestAnimationFrame(step)}else if(!active){running=false;last=0;cancelAnimationFrame(frame)}},reset(){running=false;cancelAnimationFrame(frame);clearTimeout(fade);elapsed=0;last=0;index=-1;element=null;lines=[]}};
})();
